always_ff @(posedge clk) begin
    if (reset) begin
        count <= '0;
        wrap_pulse <= 1'b0;
    end else begin
        wrap_pulse <= 1'b0;
        if (count == LIMIT-1) begin
            count <= '0;
            wrap_pulse <= 1'b1;
        end else begin
            count <= count + 1'b1;
        end
    end
end

always_ff @(posedge clk) begin
    if (reset) begin
        divider <= '0;
        tick <= 1'b0;
    end else begin
        tick <= 1'b0;
        if (divider == DIVISOR-1) begin
            divider <= '0;
            tick <= 1'b1;
        end else begin
            divider <= divider + 1'b1;
        end
    end
end

always_ff @(posedge clk) begin
    if (reset) begin
        timer_count <= '0;
        timer_busy <= 1'b0;
        timer_done <= 1'b0;
    end else begin
        timer_done <= 1'b0;
        if (start) begin
            timer_count <= '0;
            timer_busy <= 1'b1;
        end else if (timer_busy && timer_count == INTERVAL-1) begin
            timer_busy <= 1'b0;
            timer_done <= 1'b1;
        end else if (timer_busy) begin
            timer_count <= timer_count + 1'b1;
        end
    end
end

always_ff @(posedge clk) begin
